// Request validation helpers.

// Conversation ids are generated by the frontend (UUIDs). Accept letters, digits, "-" and "_" only.
export const THREAD_ID_PATTERN = /^[A-Za-z0-9_-]{1,100}$/;

export const isValidThreadId = (value) => typeof value === "string" && THREAD_ID_PATTERN.test(value);

/**
 * Validate the body of POST /api/chat.
 * Returns { ok: true, threadId, message } or { ok: false, status, error }.
 */
export const validateChatBody = (body, maxMessageChars) => {
    const threadId = typeof body?.threadId === "string" ? body.threadId.trim() : "";
    const message = typeof body?.message === "string" ? body.message.trim() : "";
    if (!threadId || !message) return { ok: false, status: 400, error: "Both threadId and message are required." };
    if (threadId.length > 100) return { ok: false, status: 400, error: "threadId is too long." };
    if (!isValidThreadId(threadId)) return { ok: false, status: 400, error: "threadId may contain only letters, digits, '-' and '_'." };
    if (message.length > maxMessageChars) {
        return { ok: false, status: 413, error: `Messages must be ${maxMessageChars} characters or fewer.` };
    }
    return { ok: true, threadId, message };
};
